READ_ROOTS = {"Select", "Union", "Intersect", "Except"}
MUTATIONS = {"Insert", "Update", "Delete", "Drop", "Create", "Alter"}
BLOCKED = {"pg_sleep", "pg_read_file", "set_config"}


def walk(node):
    """Yield a node and every node below it. A node is (type, name, children)."""
    yield node
    for child in node[2]:
        yield from walk(child)


def validate(tree):
    """Raise ValueError to refuse the parsed statement; return None to allow it."""
    if tree[0] in MUTATIONS:
        raise ValueError(f"{tree[0]} is not a read")
    for node in walk(tree):
        if node is not tree and node[0] in MUTATIONS:
            raise ValueError(f"a nested {node[0]} is not a read")
        if node[0] == "Func" and node[1] in BLOCKED:
            raise ValueError(f"function {node[1]} is blocked")

questions.solution:
READ_ROOTS = {"Select", "Union", "Intersect", "Except"}
MUTATIONS = {"Insert", "Update", "Delete", "Drop", "Create", "Alter"}
BLOCKED = {"pg_sleep", "pg_read_file", "set_config"}


def walk(node):
    """Yield a node and every node below it. A node is (type, name, children)."""
    yield node
    for child in node[2]:
        yield from walk(child)


def validate(tree):
    """Raise ValueError to refuse the parsed statement; return None to allow it."""
    # An opaque node is a node no check below can see inside: refuse it anywhere.
    if any(node[0] == "Command" for node in walk(tree)):
        raise ValueError("the parser could not model this statement")
    if tree[0] not in READ_ROOTS:
        raise ValueError(f"{tree[0]} is not a read")
    for node in walk(tree):
        if node is not tree and node[0] in MUTATIONS:
            raise ValueError(f"a nested {node[0]} is not a read")
        if node[0] == "Func" and node[1] in BLOCKED:
            raise ValueError(f"function {node[1]} is blocked")
